// Lookup para resolver descripciones de RA y Criterios
const CRIT_LOOKUP = new Map<string, { es: string; ca: string; ra: string }>();
const RA_LOOKUP = new Map<string, { es: string; ca: string }>();

for (const r of CFGM_PELUQUERIA_RAS_DATA) {
  RA_LOOKUP.set(`${r.moduleCode}_${r.id}`, { es: r.description_es, ca: r.description_ca });
  const raNum = r.id.replace(/\D/g, '');
  r.criterios_es.forEach((c_es, idx) => {
    const val = { es: c_es, ca: r.criterios_ca[idx], ra: r.id };
    const letter = c_es[0];
    CRIT_LOOKUP.set(`${r.moduleCode}-${raNum}${letter}`, val);
    CRIT_LOOKUP.set(`${r.moduleCode}-${letter}`, val);
    CRIT_LOOKUP.set(`${r.moduleCode}-${raNum}${idx + 1}`, val);
  });
}

function expandConnection(c: { s: string; t: string; k: string[]; rel: any; r: string[]; a: string[] }): IntermodularConnection {
  const tgtModCode = c.t.split('-')[0];
  const mName = MOD_NAMES[tgtModCode];
  const tgtCritInfo = CRIT_LOOKUP.get(c.t)!;
  const tgtRaCode = tgtCritInfo.ra;
  const raDesc = RA_LOOKUP.get(`${tgtModCode}_${tgtRaCode}`)!;
  
  const acts = c.a.map((id: string) => A[id]);
  const firstAct = acts[0];
  
  const relatedCriteria: RelatedCriteriaItem[] = c.r.map((code: string) => {
    const modCode = code.split('-')[0];
    const mInfo = MOD_NAMES[modCode];
    const critInfo = CRIT_LOOKUP.get(code)!;
    return {
      moduleCode: modCode,
      moduleName_es: mInfo.es,
      moduleName_ca: mInfo.ca,
      criteria: `${code}. ${critInfo.es}`,
      criteria_es: `${code}. ${critInfo.es}`,
      criteria_ca: `${code}. ${critInfo.ca}`
    };
  });

  return {
    title_es: `Conexión curricular: ${c.s} ↔ ${c.t} (${mName.es})`,
    title_ca: `Connexió curricular: ${c.s} ↔ ${c.t} (${mName.ca})`,
    targetModuleCode: tgtModCode,
    targetModuleName_es: mName.es,
    targetModuleName_ca: mName.ca,
    targetRaCode: tgtRaCode,
    targetRaText_es: raDesc.es,
    targetRaText_ca: raDesc.ca,
    sourceCriteria: c.s,
    criteriaKeys: c.k,
    relatedCriteria,
    relationType: c.rel,
    justification_es: firstAct.justification_es!,
    justification_ca: firstAct.justification_ca!,
    activities: acts
  };
}

